CREATE TABLE public.departamento_relacoes (departamento_id text NOT NULL REFERENCES public.departamentos_portal(id),lider_email text NOT NULL,liderado_email text NOT NULL,PRIMARY KEY(departamento_id,lider_email,liderado_email),CHECK(lider_email<>liderado_email));
GRANT ALL ON public.departamento_relacoes TO service_role;
ALTER TABLE public.departamento_relacoes ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE definicao text; BEGIN SELECT pg_get_functiondef('public.aplicar_departamentos(jsonb)'::regprocedure) INTO definicao; definicao := replace(definicao,'UPDATE public.departamentos_sincronizacao SET ativada=true', E'DELETE FROM public.departamento_relacoes WHERE lider_email IS NOT NULL;\nFOR rel IN SELECT value FROM jsonb_array_elements(_snapshot->''hierarquia'') LOOP\nINSERT INTO public.departamento_relacoes(departamento_id,lider_email,liderado_email) VALUES(rel->>''departamento'',rel->>''lider'',rel->>''liderado'') ON CONFLICT DO NOTHING;\nEND LOOP;\nUPDATE public.departamentos_sincronizacao SET ativada=true'); EXECUTE definicao; END $$;
CREATE OR REPLACE FUNCTION public.meu_escopo_departamento() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT jsonb_build_object('departamento',(SELECT d.nome FROM public.profissional_departamento pd JOIN public.departamentos_portal d ON d.id=pd.departamento_id WHERE pd.usuario_id=auth.uid()),'gestaoPessoas',CASE WHEN EXISTS(SELECT 1 FROM public.departamentos_sincronizacao WHERE id AND ativada) THEN EXISTS(SELECT 1 FROM public.usuario_perfis up JOIN public.perfis pf ON pf.id=up.perfil_id AND pf.ativo JOIN public.departamentos_portal d ON d.id=pf.departamento_sp_id WHERE up.usuario_id=auth.uid() AND upper(trim(d.nome)) IN ('GESTÃO DE PESSOAS','ADMINISTRATIVO E GESTÃO DE PESSOAS')) ELSE EXISTS(SELECT 1 FROM public.usuario_perfis up JOIN public.perfis pf ON pf.id=up.perfil_id AND pf.ativo WHERE up.usuario_id=auth.uid() AND pf.nome='Gestão de Pessoas') END,'emails',coalesce((SELECT jsonb_agg(email) FROM (SELECT lower(trim(p.email)) as email FROM public.profiles p WHERE p.id=auth.uid() AND p.is_active UNION SELECT h.liderado_email FROM public.departamento_relacoes h JOIN public.profiles p ON lower(trim(p.email))=h.lider_email AND p.is_active JOIN public.perfis pf ON pf.departamento_sp_id=h.departamento_id AND pf.ativo JOIN public.usuario_perfis up ON up.perfil_id=pf.id AND up.usuario_id=p.id WHERE p.id=auth.uid() AND EXISTS(SELECT 1 FROM public.perfil_permissoes pp WHERE pp.perfil_id=pf.id AND pp.permissao='pendencias.liderados')) e),'[]'::jsonb)) WHERE public.is_active_user(auth.uid());
$$;
CREATE OR REPLACE FUNCTION public.pode_enviar_como(_perfil_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT public.tem_permissao('avisos.publicar') AND EXISTS(SELECT 1 FROM public.usuario_perfis up JOIN public.perfis p ON p.id=up.perfil_id WHERE up.usuario_id=auth.uid() AND up.perfil_id=_perfil_id AND p.ativo AND (p.sistema OR ((p.departamento_sp_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public.departamentos_sincronizacao WHERE id AND ativada)) AND EXISTS(SELECT 1 FROM public.perfil_permissoes pp WHERE pp.perfil_id=p.id AND pp.permissao='avisos.publicar'))));
$$;
CREATE OR REPLACE FUNCTION public.gere_aviso(_autor uuid,_perfil uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_active_user(auth.uid()) AND ((_autor=auth.uid() AND public.tem_permissao('avisos.publicar')) OR public.tem_permissao('avisos.gerenciar') OR public.pode_enviar_como(_perfil)); $$;
COMMENT ON TABLE public.departamento_relacoes IS 'Authoritative projected SharePoint leadership emails; reports do not need a portal account to have their assigned priorities consulted.';